// src/utils/function_slug.ts
/** The rule the platform enforces on function slugs, so a bad one fails before any write. */
const FUNCTION_SLUG_PATTERN = /^[a-z0-9]{1,20}$/;
const FUNCTION_SLUG_HELP = "Use 1-20 lowercase letters and digits (no hyphens or other characters).";
const deriveFunctionSlug = (value) => value.toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 20);
export { FUNCTION_SLUG_HELP, FUNCTION_SLUG_PATTERN, deriveFunctionSlug };
